head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gJongcode = ""; // 시장구분코드
scwin.gFilterType = ""; // "S":종목검색버튼,"O"
scwin.skw = "";
scwin.tpcd = $c.frame.path("../").js_market; // 세션의 시장구분

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const sbmOptions = {
            id : "sbm_dts_jongmok",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_jongmok=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        let pJongNm = dts_jongmok.getCellData(dts_jongmok.getRowPosition(), "ISU_KOR_ABBRV");
        if (scwin.tpcd === '1' || scwin.tpcd === '2') {
            rdo_upjong.setValue(scwin.tpcd);
            rdo_upjong.setDisabled(true);
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_jongmok_OnLoadError
 * @description dts_jongmok 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_jongmok_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_jongmok);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00003.dts_jongmok_OnLoadError" });
    }
};

/**
 * @method
 * @name rdo_upjong_onselchange
 * @description rdo_upjong onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_upjong_onselchange = function() {
    try {
        txb_jongmokName.setValue("");
        scwin.gJongcode = rdo_upjong.getValue();
        scwin.gFilterType = "O";
        if (scwin.gJongcode === "0") {
            dts_jongmok.UseFilter = false;
            dts_jongmok.reset();
        } else {
            dts_jongmok.UseFilter = true;
            dts_jongmok.Filter();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00003.rdo_upjong_onselchange" });
    }
};

/**
 * @method
 * @name dts_jongmok_OnFilter
 * @description jongmok On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_jongmok_OnFilter = function(row) {
    try {
        if (scwin.skw !== "") {
            f1 = (dts_jongmok.getCellData(row, "ISU_KOR_ABBRV")).toUpperCase();
            f2 = (dts_jongmok.getCellData(row, "ISU_KOR_NM")).toUpperCase();
            if (f1.indexOf(scwin.skw) !== -1) {
                return true;
            } else if (f2.indexOf(scwin.skw) !== -1) {
                return true;
            } else {
                return false;
            }
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00003.dts_jongmok_OnFilter" });
    }
};

/**
 * @method
 * @name grd_jongmok_OnKeyPress
 * @description grd jongmok On Key Press 처리
 * @param {*} kcode kcode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_jongmok_OnKeyPress = async function(kcode) {
    try {
        if (kcode === '13') {
            await scwin.Confirm();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00003.grd_jongmok_OnKeyPress" });
    }
};

/**
 * @method
 * @name grd_jongmok_OnDblClick
 * @description grd_jongmok 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_jongmok_OnDblClick = async function(row, colid) {
    try {
        await scwin.Confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDCOM00003.grd_jongmok_OnDblClick" });
    }
};

/**
 * @method
