 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_search_onclick = function() {
    try {
        $c.stockSearch.JongmokSearch(window.event.keyCode);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDCOM00003.img_search_onclick" });
    }
};

